#!/usr/bin/env python3
import sys, os, re, math, time, json, base64, urllib.parse, unicodedata
from decimal import Decimal, InvalidOperation
from datetime import datetime, timezone, timedelta

VERSION="jq-build-f77602d"
BUILD_CONFIGURATION="--disable-docs --with-oniguruma=builtin --enable-static --enable-all-static --prefix=/usr/local"

# ---------- Numbers ----------
class Num:
    __slots__=('v','dec')
    def __init__(self, v, dec=None):
        self.v=float(v)
        self.dec=dec
    def __repr__(self):
        return f"Num({self.v!r},{self.dec!r})"

def num_from_literal(text):
    try:
        dec=Decimal(text)
    except Exception:
        dec=Decimal(0)
        return Num(float(text) if False else 0.0, None)
    try:
        v=float(dec)
    except Exception:
        v=math.inf if dec>0 else (-math.inf if dec<0 else 0.0)
    return Num(v, dec)
def num_float(x):
    try:
        return Num(float(x), None)
    except Exception:
        return Num(0.0,None)
def num_int(i):
    # ints that fit
    return Num(float(i), None)
def make_num_from_python(x):
    if isinstance(x, Num):
        return x
    if isinstance(x,bool):
        return x
    if isinstance(x,int):
        # preserve as literal for small? Runtime generated ints should be float nums
        return Num(float(x), None)
    if isinstance(x,float):
        return Num(x,None)
    if isinstance(x,Decimal):
        try: v=float(x)
        except Exception: v=math.inf
        return Num(v,x)
    return x

DBL_MAX=1.7976931348623157e308
def format_float(v):
    if math.isnan(v):
        return "null"
    if math.isinf(v):
        return ("-" if v<0 else "")+"1.7976931348623157e+308"
    if v==0.0:
        return "-0" if math.copysign(1.0,v)<0 else "0"
    # get digits/decpt from repr
    r=repr(v)
    # r may be like '1e+15', '123.45', '0.0001'
    # Use Decimal(repr) to get digit tuple
    d=Decimal(r)
    sign, digits_tuple, exp = d.as_tuple()
    digits=''.join(str(x) for x in digits_tuple)
    # strip leading zeros (shouldn't)
    # Decimal tuple may have trailing zeros? repr shortest shouldn't except .0 cases: e.g. 1000000000000000.0 repr is that, Decimal digits include zeros
    # normalize: strip trailing zeros and adjust exp
    # But for values like 100.0, digits='1000'? Actually Decimal('100.0') digits (1,0,0,0) exp -1
    while len(digits)>1 and digits.endswith('0'):
        digits=digits[:-1]
        exp+=1
    while len(digits)>1 and digits.startswith('0'):
        digits=digits[1:]
        # value = 0.digits *10^decpt, leading zero removal doesn't change decpt? handle via decpt below recompute?
        # Decimal normalized shouldn't have leading zeros
    decpt=exp+len(digits)  # value = digits *10^exp, decimal point after decpt digits from left of 0.xxx form
    # fixed if decpt >= -3 and decpt-len(digits) <=15 (derived)
    if decpt>=-3 and (decpt-len(digits))<=15:
        if decpt<=0:
            out="0."+("0"*(-decpt))+digits
        elif decpt>=len(digits):
            out=digits+("0"*(decpt-len(digits)))
        else:
            out=digits[:decpt]+"."+digits[decpt:]
        return ("-" if v<0 else "")+out
    else:
        # scientific
        mant=digits[0]
        if len(digits)>1:
            mant+="."+digits[1:]
        e=decpt-1
        return ("-" if v<0 else "")+mant+f"e{e:+03d}"
def format_num(n):
    if isinstance(n, Num):
        if n.dec is not None:
            return str(n.dec)
        return format_float(n.v)
    return str(n)

def num_value(v):
    if isinstance(v, Num):
        return v.v
    raise TypeError

def compare_numbers(a,b):
    # returns -1,0,1
    # NaN handling: NaN is smallest among numbers
    av=a.v; bv=b.v
    a_nan=isinstance(av,float) and math.isnan(av)
    b_nan=isinstance(bv,float) and math.isnan(bv)
    if a_nan and b_nan:
        return 0
    if a_nan:
        return -1
    if b_nan:
        return 1
    if a.dec is not None and b.dec is not None:
        if a.dec<b.dec: return -1
        if a.dec>b.dec: return 1
        return 0
    if a.v<b.v: return -1
    if a.v>b.v: return 1
    return 0

def numbers_equal(a,b):
    if a.dec is not None and b.dec is not None:
        return a.dec==b.dec
    # float equality; NaN !=
    if math.isnan(a.v) or math.isnan(b.v):
        return False
    return a.v==b.v

# ---------- values helpers ----------
def type_name(v):
    if v is None: return "null"
    if isinstance(v,bool): return "boolean"
    if isinstance(v,Num): return "number"
    if isinstance(v,str): return "string"
    if isinstance(v,list): return "array"
    if isinstance(v,dict): return "object"
    return "null"

def truthy(v):
    return not (v is None or v is False)

def deep_copy(v):
    if isinstance(v,list):
        return [deep_copy(x) for x in v]
    if isinstance(v,dict):
        return {k:deep_copy(x) for k,x in v.items()}
    return v

def jq_cmp(a,b):
    # type order
    def rank(v):
        if v is None: return 0
        if v is False: return 1
        if v is True: return 2
        if isinstance(v,Num): return 3
        if isinstance(v,str): return 4
        if isinstance(v,list): return 5
        if isinstance(v,dict): return 6
        return 0
    ra, rb = rank(a), rank(b)
    if ra!=rb:
        return -1 if ra<rb else 1
    if isinstance(a,Num) and isinstance(b,Num):
        return compare_numbers(a,b)
    if isinstance(a,str) and isinstance(b,str):
        return -1 if a<b else (1 if a>b else 0)
    if isinstance(a,list) and isinstance(b,list):
        for x,y in zip(a,b):
            c=jq_cmp(x,y)
            if c: return c
        if len(a)<len(b): return -1
        if len(a)>len(b): return 1
        return 0
    if isinstance(a,dict) and isinstance(b,dict):
        ka=sorted(a.keys()); kb=sorted(b.keys())
        c=jq_cmp([Num(float(0))]*0, []) # dummy
        # compare sorted keys as arrays of strings
        for x,y in zip(ka,kb):
            if x<y: return -1
            if x>y: return 1
        if len(ka)<len(kb): return -1
        if len(ka)>len(kb): return 1
        for k in ka:
            c=jq_cmp(a[k],b[k])
            if c: return c
        return 0
    return 0

def jq_equal(a,b):
    if isinstance(a,Num) and isinstance(b,Num):
        return numbers_equal(a,b)
    if type_name(a)!=type_name(b):
        # bool check: python bool vs ...
        if isinstance(a,bool)!=isinstance(b,bool):
            return False
        return False
    if isinstance(a,list):
        return len(a)==len(b) and all(jq_equal(x,y) for x,y in zip(a,b))
    if isinstance(a,dict):
        if set(a.keys())!=set(b.keys()): return False
        return all(jq_equal(a[k],b[k]) for k in a)
    return a==b

def to_py_plain(v):
    # for internal sorting keys etc (convert Num to float/dec string)
    return v

# ---------- JSON output rendering ----------
def escape_string(s, ascii_only=False):
    out=[]
    for ch in s:
        o=ord(ch)
        if ch=='"': out.append('\\"')
        elif ch=='\\': out.append('\\\\')
        elif ch=='\b': out.append('\\b')
        elif ch=='\f': out.append('\\f')
        elif ch=='\n': out.append('\\n')
        elif ch=='\r': out.append('\\r')
        elif ch=='\t': out.append('\\t')
        elif o<0x20 or o==0x7f:
            out.append('\\u%04x'%o)
        elif ascii_only and o>0x7e:
            if o<=0xFFFF:
                out.append('\\u%04x'%o)
            else:
                # surrogate pair
                o2=o-0x10000
                hi=0xD800+(o2>>10)
                lo=0xDC00+(o2&0x3FF)
                out.append('\\u%04x\\u%04x'%(hi,lo))
        elif 0xD800<=o<=0xDFFF:
            out.append('\\u%04x'%o)
        else:
            out.append(ch)
    return '"'+''.join(out)+'"'

class OutputOpts:
    def __init__(self):
        self.compact=False
        self.raw=False
        self.raw0=False
        self.join=False
        self.ascii=False
        self.sort_keys=False
        self.color=False
        self.monochrome=False
        self.tab=False
        self.indent=2
        self.seq=False
        self.unbuffered=False

# color codes defaults: null,false,true,number,string,array,object,key
DEFAULT_COLORS=["0;90","0;39","0;39","0;39","0;32","1;39","1;39","1;34"]
def get_colors():
    env=os.environ.get("JQ_COLORS")
    if env is None or env=="":
        return DEFAULT_COLORS[:]
    parts=env.split(":")
    # validate: each part should be digits/semicolons ? jq: if invalid, print failed
    for p in parts:
        if not re.fullmatch(r'[0-9;]*', p or ""):
            # Actually empty allowed? treat invalid
            sys.stderr.write("Failed to set $JQ_COLORS\n")
            return DEFAULT_COLORS[:]
        if p=="":
            sys.stderr.write("Failed to set $JQ_COLORS\n")
            return DEFAULT_COLORS[:]
    cols=DEFAULT_COLORS[:]
    for i,p in enumerate(parts[:8]):
        cols[i]=p
    return cols

def render_value(v, opts, level=0, colors=None):
    # returns string without trailing newline
    if colors is not None:
        return render_color(v, opts, level, colors)
    if v is None:
        return "null"
    if v is True:
        return "true"
    if v is False:
        return "false"
    if isinstance(v,Num):
        return format_num(v)
    if isinstance(v,str):
        return escape_string(v, opts.ascii)
    if isinstance(v,list):
        if opts.compact:
            return "["+",".join(render_value(x,opts,level+1,colors) for x in v)+"]"
        if len(v)==0:
            return "[]"
        indent_str=get_indent(opts, level+1)
        base_indent=get_indent(opts, level)
        items=[indent_str+render_value(x,opts,level+1,colors) for x in v]
        return "[\n"+",\n".join(items)+"\n"+base_indent+"]"
    if isinstance(v,dict):
        items=list(v.items())
        if opts.sort_keys:
            items=sorted(items, key=lambda kv: kv[0])
        if opts.compact:
            return "{"+",".join(escape_string(k,opts.ascii)+":"+render_value(val,opts,level+1,colors) for k,val in items)+"}"
        if len(items)==0:
            return "{}"
        indent_str=get_indent(opts, level+1)
        base_indent=get_indent(opts, level)
        parts=[]
        for k,val in items:
            parts.append(indent_str+escape_string(k,opts.ascii)+": "+render_value(val,opts,level+1,colors))
        return "{\n"+",\n".join(parts)+"\n"+base_indent+"}"
    return "null"

def get_indent(opts, level):
    if opts.tab or opts.indent<0:
        # indent -1 means tab
        if opts.tab:
            return "\t"*level
        else:
            return "\t"*level
    return " "*(opts.indent*level)

def render_color(v, opts, level, colors):
    def wrap(code, text):
        return f"\x1b[{code}m{text}\x1b[0m"
    # colors indices
    if v is None:
        return wrap(colors[0], "null")
    if v is False:
        return wrap(colors[1], "false")
    if v is True:
        return wrap(colors[2], "true")
    if isinstance(v,Num):
        return wrap(colors[3], format_num(v))
    if isinstance(v,str):
        return wrap(colors[4], escape_string(v, opts.ascii))
    if isinstance(v,list):
        arr_c=colors[5]
        if opts.compact:
            inner=",".join([render_value(x,opts,level+1,colors) for x in v])
            # commas colored
            # rebuild with colored commas
            parts=[render_value(x,opts,level+1,colors) for x in v]
            inner=(wrap(arr_c,",")).join(parts)
            return wrap(arr_c,"[")+inner+wrap(arr_c,"]")
        if len(v)==0:
            return wrap(arr_c,"[")+wrap(arr_c,"]")
        indent_str=get_indent(opts, level+1)
        base_indent=get_indent(opts, level)
        rendered=[]
        for x in v:
            rendered.append(indent_str+render_value(x,opts,level+1,colors))
        # join with colored comma + newline
        s=wrap(arr_c,"[")+"\n"
        for i,part in enumerate(rendered):
            s+=part
            if i<len(rendered)-1:
                s+=wrap(arr_c,",")
            s+="\n"
        s+=base_indent+wrap(arr_c,"]")
        return s
    if isinstance(v,dict):
        obj_c=colors[6]
        key_c=colors[7]
        items=list(v.items())
        if opts.sort_keys:
            items=sorted(items, key=lambda kv: kv[0])
        if opts.compact:
            parts=[]
            for k,val in items:
                parts.append(wrap(key_c, escape_string(k,opts.ascii))+wrap(obj_c,":")+render_value(val,opts,level+1,colors))
            inner=(wrap(obj_c,",")).join(parts)
            return wrap(obj_c,"{")+inner+wrap(obj_c,"}")
        if len(items)==0:
            return wrap(obj_c,"{")+wrap(obj_c,"}")
        indent_str=get_indent(opts, level+1)
        base_indent=get_indent(opts, level)
        s=wrap(obj_c,"{")+"\n"
        for i,(k,val) in enumerate(items):
            s+=indent_str+wrap(key_c, escape_string(k,opts.ascii))+wrap(obj_c,":")+" "+render_value(val,opts,level+1,colors)
            if i<len(items)-1:
                s+=wrap(obj_c,",")
            s+="\n"
        s+=base_indent+wrap(obj_c,"}")
        return s
    return "null"

def compact_json(v):
    opts=OutputOpts(); opts.compact=True
    return render_value(v, opts)

def describe_value(v):
    # for errors: type (value)
    t=type_name(v)
    if t=="string":
        return f'string ({escape_string(v, False)})'
    if t=="number":
        return f'number ({format_num(v)})'
    if t=="boolean":
        return f'boolean ({"true" if v else "false"})'
    if t=="null":
        return 'null (null)'
    if t=="array":
        return f'array ({compact_json(v)})'
    if t=="object":
        return f'object ({compact_json(v)})'
    return t

def describe_plain(v):
    # e.g. Cannot use X as object key: type (value) same as above except?
    return describe_value(v)

# ---------- Errors ----------
class JQError(Exception):
    def __init__(self, message, value=None, not_string=False):
        super().__init__(message)
        self.message=message
        # value to be caught: if value is None (?) distinguish
        self.catch_value=value  # if None special handling in raise sites
        self.not_string=not_string
    def catch_val(self):
        if self.catch_value is not None or hasattr(self,'_catch_set'):
            return self.catch_value
        return self.message

class HaltException(Exception):
    def __init__(self, code):
        self.code=code
class BreakLabel(Exception):
    def __init__(self, label_id):
        self.label_id=label_id
class InputEOF(Exception):
    pass
class CompileErrorList(Exception):
    def __init__(self, errors):
        self.errors=errors # list of dicts {msg, file, line, col, span_text, source_line, caret_len, no_loc}
class ParseFailure(Exception):
    def __init__(self, msg, pos=0, line=1, col=0, expected=None, token_desc=None):
        self.msg=msg; self.pos=pos; self.line=line; self.col=col; self.expected=expected; self.token_desc=token_desc

# ---------- JSON parser (for input, fromjson, etc.) ----------
class JSONParseError(Exception):
    def __init__(self, msg, line=1, col=0):
        self.msg=msg; self.line=line; self.col=col
    def __str__(self):
        suffix=" at EOF" if "at EOF" in self.msg else ""
        # msg already includes ?
        return self.msg

class JSONParser:
    def __init__(self, text):
        self.text=text
        self.n=len(text)
        self.pos=0
        # strip BOM at start
        if self.pos<self.n and self.text[self.pos]=='\ufeff':
            self.pos+=1
    def line_col(self, pos):
        # jq line = 1 + newlines before pos, col = ?
        upto=self.text[:pos]
        line=upto.count('\n')+1
        last=upto.rfind('\n')
        col=pos-last-1 if last>=0 else pos
        # jq column seems sometimes ... we will use col as computed (maybe +?)
        return line, col
    def err(self, base_msg, pos=None, at_eof=False):
        if pos is None: pos=self.pos
        line,col=self.line_col(pos)
        if at_eof:
            msg=f"{base_msg} at EOF at line {line}, column {col}"
        else:
            msg=f"{base_msg} at line {line}, column {col}"
        raise JSONParseError(msg, line, col)
    def skip_ws(self):
        while self.pos<self.n and self.text[self.pos] in ' \t\r\n':
            self.pos+=1
    def peek(self):
        return self.text[self.pos] if self.pos<self.n else ''
    def parse_value(self):
        self.skip_ws()
        if self.pos>=self.n:
            self.err("Unfinished JSON term", at_eof=True)
        ch=self.text[self.pos]
        if ch=='{':
            return self.parse_object()
        if ch=='[':
            return self.parse_array()
        if ch=='"':
            return self.parse_string()
        if ch=='t' or ch=='f' or ch=='n':
            return self.parse_literal()
        # number-ish (including +, ., digits, -, also invalid letters fall to invalid numeric?)
        # jq treats alphabetical as invalid numeric literal ?
        # If ch is letter, treat as invalid numeric/literal depending
        if ch.isalpha():
            # consume alphanum
            start=self.pos
            while self.pos<self.n and (self.text[self.pos].isalnum() or self.text[self.pos] in '_'):
                self.pos+=1
            # line/col at end (after maybe?)
            # If EOF or newline following, jq reports at next line?
            # We'll approximate: if next char is newline, advance?
            p=self.pos
            # mimic: if at EOF, error at EOF
            if p>=self.n:
                self.err("Invalid numeric literal", pos=p, at_eof=True)
            else:
                # If invalid literal like truex handled in parse_literal else
                self.err("Invalid numeric literal", pos=p, at_eof=False)
        # number
        return self.parse_number()
    def parse_literal(self):
        start=self.pos
        for word,val in [('true',True),('false',False),('null',None)]:
            if self.text.startswith(word, self.pos):
                end=self.pos+len(word)
                # if next is alnum, invalid
                if end<self.n and (self.text[end].isalnum() or self.text[end]=='_'):
                    break
                self.pos=end
                return val
        # invalid literal: consume letters
        while self.pos<self.n and self.text[self.pos].isalpha():
            self.pos+=1
        p=self.pos
        # jq reports line after newline? skip one newline for position?
        if p<self.n and self.text[p]=='\n':
            # error position at next line col0
            line,col=self.line_col(p+1)
            raise JSONParseError(f"Invalid literal at line {line}, column {col}", line, col)
        if p>=self.n:
            self.err("Invalid literal", pos=p, at_eof=True)
        self.err("Invalid literal", pos=p)
    def parse_number(self):
        start=self.pos
        # liberal: [+-]? digits / . etc
        m=re.match(r'[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?', self.text[self.pos:])
        if not m:
            if self.pos>=self.n:
                self.err("Invalid numeric literal", at_eof=True)
            else:
                self.err("Invalid numeric literal", pos=self.pos)
        txt=m.group(0)
        self.pos+=len(txt)
        # check invalid trailing digit/dot/letter? jq: if next char is digit alnum? e.g. 1e etc parsed as 1 then, invalid numeric at following?
        # If next char is '.' or letter, may be...
        return num_from_literal(txt)
    def parse_string(self):
        # assume opening "
        self.pos+=1
        out=[]
        while True:
            if self.pos>=self.n:
                self.err("Unfinished string", at_eof=True)
            ch=self.text[self.pos]
            if ch=='"':
                self.pos+=1
                return ''.join(out)
            if ch=='\\':
                self.pos+=1
                if self.pos>=self.n:
                    self.err("Unfinished string", at_eof=True)
                esc=self.text[self.pos]
                self.pos+=1
                if esc=='"': out.append('"')
                elif esc=='\\': out.append('\\')
                elif esc=='/': out.append('/')
                elif esc=='b': out.append('\b')
                elif esc=='f': out.append('\f')
                elif esc=='n': out.append('\n')
                elif esc=='r': out.append('\r')
                elif esc=='t': out.append('\t')
                elif esc=='u':
                    # 4 hex
                    if self.pos+4>self.n:
                        self.err("Invalid characters in \\uXXXX escape", pos=self.pos+4 if self.pos+4<=self.n else self.n)
                    hexs=self.text[self.pos:self.pos+4]
                    if not re.fullmatch(r'[0-9a-fA-F]{4}', hexs):
                        # col: jq reports more
                        self.err("Invalid characters in \\uXXXX escape", pos=self.pos+2)  # approx
                    self.pos+=4
                    code=int(hexs,16)
                    if 0xD800<=code<=0xDBFF:
                        # need low surrogate
                        if self.text[self.pos:self.pos+2]=='\\u':
                            hex2=self.text[self.pos+2:self.pos+6]
                            if re.fullmatch(r'[0-9a-fA-F]{4}', hex2 or ''):
                                code2=int(hex2,16)
                                if 0xDC00<=code2<=0xDFFF:
                                    self.pos+=6
                                    out.append(chr(0x10000+((code-0xD800)<<10)+(code2-0xDC00)))
                                    continue
                        self.err("Invalid \\uXXXX\\uXXXX surrogate pair escape", pos=self.pos)
                    elif 0xDC00<=code<=0xDFFF:
                        self.err("Invalid \\uXXXX\\uXXXX surrogate pair escape", pos=self.pos)
                    else:
                        out.append(chr(code))
                else:
                    self.err("Invalid escape", pos=self.pos-1)
            elif ord(ch)<0x20:
                self.err("Invalid string: control characters from U+0000 through U+001F must be escaped", pos=self.pos+1)
            else:
                out.append(ch)
                self.pos+=1
    def parse_array(self):
        self.pos+=1 # [
        arr=[]
        self.skip_ws()
        if self.peek()==']':
            self.pos+=1
            return arr
        while True:
            self.skip_ws()
            if self.pos>=self.n:
                self.err("Unfinished JSON term", at_eof=True)
            if self.peek()==']':
                # trailing comma case
                self.err("Expected another array element", pos=self.pos+1 if False else self.pos)
            arr.append(self.parse_value())
            self.skip_ws()
            if self.pos>=self.n:
                self.err("Unfinished JSON term", at_eof=True)
            ch=self.text[self.pos]
            if ch==',':
                self.pos+=1
                continue
            elif ch==']':
                self.pos+=1
                return arr
            else:
                self.err("Expected separator between values", pos=self.pos)
    def parse_object(self):
        self.pos+=1
        obj={}
        self.skip_ws()
        if self.peek()=='}':
            self.pos+=1
            return obj
        while True:
            self.skip_ws()
            if self.pos>=self.n:
                self.err("Unfinished JSON term", at_eof=True)
            if self.peek()=='}':
                self.err("Expected another key-value pair", pos=self.pos)
            if self.peek()!='"':
                # jq reports Invalid numeric literal for {a:1} at column after a?
                self.err("Invalid numeric literal", pos=self.pos+1)
            key=self.parse_string()
            self.skip_ws()
            if self.pos>=self.n:
                self.err("Unfinished JSON term", at_eof=True)
            if self.text[self.pos]!=':':
                self.err("Expected separator between values", pos=self.pos+1 if self.pos<self.n else self.pos)
            self.pos+=1
            self.skip_ws()
            if self.pos<self.n and self.text[self.pos]=='}':
                # missing value
                self.err("Unmatched '}'", pos=self.pos)  # non-stream gives Unmatched
            val=self.parse_value()
            obj[key]=val
            self.skip_ws()
            if self.pos>=self.n:
                self.err("Unfinished JSON term", at_eof=True)
            ch=self.text[self.pos]
            if ch==',':
                self.pos+=1
                continue
            elif ch=='}':
                self.pos+=1
                return obj
            else:
                self.err("Expected separator between values", pos=self.pos)
    def parse_all_values(self):
        # generator of (value, end_line)
        vals=[]
        while True:
            self.skip_ws()
            if self.pos>=self.n:
                break
            start_pos=self.pos
            v=self.parse_value()
            end_line=self.line_col(self.pos-1 if self.pos>0 else self.pos)[0] if self.pos>0 else 1
            # jq input_line_number is line number at end of value (1-indexed line of last char)
            vals.append((v, end_line))
        return vals

def parse_json_text_all(text):
    p=JSONParser(text)
    return p.parse_all_values()
def parse_json_single(text):
    p=JSONParser(text)
    p.skip_ws()
    if p.pos>=p.n:
        raise JSONParseError("EOF while parsing a value at line 1, column 0",1,0) # placeholder
    v=p.parse_value()
    p.skip_ws()
    if p.pos<p.n:
        # extra?
        # jq fromjson: parsing expects? If extra values, maybe return first? Test "1 2"|fromjson
        pass
    return v

