    if isinstance(x,int):
        # preserve as literal for small? Runtime generated ints should be float nums
        return Num(float(x), None)
    if isinstance(x,float):
        return Num(x,None)
    if isinstance(x,Decimal):
        try: v=float(x)
        except Exception: v=math.inf
        return Num(v,x)
    return x

DBL_MAX=1.7976931348623157e308
def format_float(v):
    if math.isnan(v):
        return "null"
    if math.isinf(v):
        return ("-" if v<0 else "")+"1.7976931348623157e+308"
    if v==0.0:
        return "-0" if math.copysign(1.0,v)<0 else "0"
    # get digits/decpt from repr
    r=repr(v)
    # r may be like '1e+15', '123.45', '0.0001'
    # Use Decimal(repr) to get digit tuple
    d=Decimal(r)
    sign, digits_tuple, exp = d.as_tuple()
    digits=''.join(str(x) for x in digits_tuple)
    # strip leading zeros (shouldn't)
    # Decimal tuple may have trailing zeros? repr shortest shouldn't except .0 cases: e.g. 1000000000000000.0 repr is that, Decimal digits include zeros
    # normalize: strip trailing zeros and adjust exp
    # But for values like 100.0, digits='1000'? Actually Decimal('100.0') digits (1,0,0,0) exp -1
    while len(digits)>1 and digits.endswith('0'):
        digits=digits[:-1]
        exp+=1
    while len(digits)>1 and digits.startswith('0'):
        digits=digits[1:]
        # value = 0.digits *10^decpt, leading zero removal doesn't change decpt? handle via decpt below recompute?
        # Decimal normalized shouldn't have leading zeros
    decpt=exp+len(digits)  # value = digits *10^exp, decimal point after decpt digits from left of 0.xxx form
    # fixed if decpt >= -3 and decpt-len(digits) <=15 (derived)
    if decpt>=-3 and (decpt-len(digits))<=15:
        if decpt<=0:
            out="0."+("0"*(-decpt))+digits
        elif decpt>=len(digits):
            out=digits+("0"*(decpt-len(digits)))
        else:
            out=digits[:decpt]+"."+digits[decpt:]
        return ("-" if v<0 else "")+out
    else:
        # scientific
        mant=digits[0]
        if len(digits)>1:
            mant+="."+digits[1:]
        e=decpt-1
        return ("-" if v<0 else "")+mant+f"e{e:+03d}"
def format_num(n):
    if isinstance(n, Num):
        if n.dec is not None:
            return str(n.dec)
        return format_float(n.v)
    return str(n)

def num_value(v):
    if isinstance(v, Num):
        return v.v
    raise TypeError

def compare_numbers(a,b):
    # returns -1,0,1
    # NaN handling: NaN is smallest among numbers
    av=a.v; bv=b.v
    a_nan=isinstance(av,float) and math.isnan(av)
    b_nan=isinstance(bv,float) and math.isnan(bv)
    if a_nan and b_nan:
        return 0
    if a_nan:
        return -1
    if b_nan:
        return 1
    if a.dec is not None and b.dec is not None:
        if a.dec<b.dec: return -1
        if a.dec>b.dec: return 1
        return 0
    if a.v<b.v: return -1
    if a.v>b.v: return 1
    return 0

def numbers_equal(a,b):
    if a.dec is not None and b.dec is not None:
        return a.dec==b.dec
    # float equality; NaN !=
    if math.isnan(a.v) or math.isnan(b.v):
        return False
    return a.v==b.v

