def type_name(v):
    if v is None: return "null"
    if isinstance(v,bool): return "boolean"
    if isinstance(v,Num): return "number"
    if isinstance(v,str): return "string"
    if isinstance(v,list): return "array"
    if isinstance(v,dict): return "object"
    return "null"

def truthy(v):
    return not (v is None or v is False)

def deep_copy(v):
    if isinstance(v,list):
        return [deep_copy(x) for x in v]
    if isinstance(v,dict):
        return {k:deep_copy(x) for k,x in v.items()}
    return v

def jq_cmp(a,b):
    # type order
    def rank(v):
        if v is None: return 0
        if v is False: return 1
        if v is True: return 2
        if isinstance(v,Num): return 3
        if isinstance(v,str): return 4
        if isinstance(v,list): return 5
        if isinstance(v,dict): return 6
        return 0
    ra, rb = rank(a), rank(b)
    if ra!=rb:
        return -1 if ra<rb else 1
    if isinstance(a,Num) and isinstance(b,Num):
        return compare_numbers(a,b)
    if isinstance(a,str) and isinstance(b,str):
        return -1 if a<b else (1 if a>b else 0)
    if isinstance(a,list) and isinstance(b,list):
        for x,y in zip(a,b):
            c=jq_cmp(x,y)
            if c: return c
        if len(a)<len(b): return -1
        if len(a)>len(b): return 1
        return 0
    if isinstance(a,dict) and isinstance(b,dict):
        ka=sorted(a.keys()); kb=sorted(b.keys())
        c=jq_cmp([Num(float(0))]*0, []) # dummy
        # compare sorted keys as arrays of strings
        for x,y in zip(ka,kb):
            if x<y: return -1
            if x>y: return 1
        if len(ka)<len(kb): return -1
        if len(ka)>len(kb): return 1
        for k in ka:
            c=jq_cmp(a[k],b[k])
            if c: return c
        return 0
    return 0

def jq_equal(a,b):
    if isinstance(a,Num) and isinstance(b,Num):
        return numbers_equal(a,b)
    if type_name(a)!=type_name(b):
        # bool check: python bool vs ...
        if isinstance(a,bool)!=isinstance(b,bool):
            return False
        return False
    if isinstance(a,list):
        return len(a)==len(b) and all(jq_equal(x,y) for x,y in zip(a,b))
    if isinstance(a,dict):
        if set(a.keys())!=set(b.keys()): return False
        return all(jq_equal(a[k],b[k]) for k in a)
    return a==b

def to_py_plain(v):
    # for internal sorting keys etc (convert Num to float/dec string)
    return v

# ---------- JSON output rendering ----------
def escape_string(s, ascii_only=False):
    out=[]
    for ch in s:
        o=ord(ch)
        if ch=='"': out.append('\\"')
        elif ch=='\\': out.append('\\\\')
        elif ch=='\b': out.append('\\b')
        elif ch=='\f': out.append('\\f')
        elif ch=='\n': out.append('\\n')
        elif ch=='\r': out.append('\\r')
        elif ch=='\t': out.append('\\t')
        elif o<0x20 or o==0x7f:
            out.append('\\u%04x'%o)
        elif ascii_only and o>0x7e:
            if o<=0xFFFF:
                out.append('\\u%04x'%o)
            else:
                # surrogate pair
                o2=o-0x10000
                hi=0xD800+(o2>>10)
                lo=0xDC00+(o2&0x3FF)
                out.append('\\u%04x\\u%04x'%(hi,lo))
        elif 0xD800<=o<=0xDFFF:
            out.append('\\u%04x'%o)
        else:
            out.append(ch)
    return '"'+''.join(out)+'"'

class OutputOpts:
    def __init__(self):
        self.compact=False
        self.raw=False
        self.raw0=False
        self.join=False
        self.ascii=False
        self.sort_keys=False
        self.color=False
        self.monochrome=False
        self.tab=False
        self.indent=2
        self.seq=False
        self.unbuffered=False

# color codes defaults: null,false,true,number,string,array,object,key
DEFAULT_COLORS=["0;90","0;39","0;39","0;39","0;32","1;39","1;39","1;34"]
def get_colors():
    env=os.environ.get("JQ_COLORS")
    if env is None or env=="":
        return DEFAULT_COLORS[:]
    parts=env.split(":")
    # validate: each part should be digits/semicolons ? jq: if invalid, print failed
    for p in parts:
        if not re.fullmatch(r'[0-9;]*', p or ""):
            # Actually empty allowed? treat invalid
            sys.stderr.write("Failed to set $JQ_COLORS\n")
            return DEFAULT_COLORS[:]
        if p=="":
            sys.stderr.write("Failed to set $JQ_COLORS\n")
            return DEFAULT_COLORS[:]
    cols=DEFAULT_COLORS[:]
    for i,p in enumerate(parts[:8]):
        cols[i]=p
    return cols

def render_value(v, opts, level=0, colors=None):
    # returns string without trailing newline
    if colors is not None:
        return render_color(v, opts, level, colors)
    if v is None:
        return "null"
    if v is True:
        return "true"
    if v is False:
        return "false"
    if isinstance(v,Num):
        return format_num(v)
    if isinstance(v,str):
        return escape_string(v, opts.ascii)
    if isinstance(v,list):
        if opts.compact:
            return "["+",".join(render_value(x,opts,level+1,colors) for x in v)+"]"
        if len(v)==0:
            return "[]"
        indent_str=get_indent(opts, level+1)
        base_indent=get_indent(opts, level)
        items=[indent_str+render_value(x,opts,level+1,colors) for x in v]
        return "[\n"+",\n".join(items)+"\n"+base_indent+"]"
    if isinstance(v,dict):
        items=list(v.items())
        if opts.sort_keys:
            items=sorted(items, key=lambda kv: kv[0])
        if opts.compact:
            return "{"+",".join(escape_string(k,opts.ascii)+":"+render_value(val,opts,level+1,colors) for k,val in items)+"}"
        if len(items)==0:
            return "{}"
        indent_str=get_indent(opts, level+1)
        base_indent=get_indent(opts, level)
        parts=[]
        for k,val in items:
            parts.append(indent_str+escape_string(k,opts.ascii)+": "+render_value(val,opts,level+1,colors))
        return "{\n"+",\n".join(parts)+"\n"+base_indent+"}"
    return "null"

def get_indent(opts, level):
    if opts.tab or opts.indent<0:
        # indent -1 means tab
        if opts.tab:
            return "\t"*level
        else:
            return "\t"*level
    return " "*(opts.indent*level)

def render_color(v, opts, level, colors):
    def wrap(code, text):
        return f"\x1b[{code}m{text}\x1b[0m"
    # colors indices
    if v is None:
        return wrap(colors[0], "null")
    if v is False:
        return wrap(colors[1], "false")
    if v is True:
        return wrap(colors[2], "true")
    if isinstance(v,Num):
        return wrap(colors[3], format_num(v))
    if isinstance(v,str):
        return wrap(colors[4], escape_string(v, opts.ascii))
    if isinstance(v,list):
        arr_c=colors[5]
        if opts.compact:
            inner=",".join([render_value(x,opts,level+1,colors) for x in v])
            # commas colored
            # rebuild with colored commas
            parts=[render_value(x,opts,level+1,colors) for x in v]
            inner=(wrap(arr_c,",")).join(parts)
            return wrap(arr_c,"[")+inner+wrap(arr_c,"]")
        if len(v)==0:
            return wrap(arr_c,"[")+wrap(arr_c,"]")
        indent_str=get_indent(opts, level+1)
        base_indent=get_indent(opts, level)
        rendered=[]
        for x in v:
            rendered.append(indent_str+render_value(x,opts,level+1,colors))
        # join with colored comma + newline
        s=wrap(arr_c,"[")+"\n"
        for i,part in enumerate(rendered):
            s+=part
            if i<len(rendered)-1:
                s+=wrap(arr_c,",")
            s+="\n"
        s+=base_indent+wrap(arr_c,"]")
        return s
    if isinstance(v,dict):
        obj_c=colors[6]
        key_c=colors[7]
        items=list(v.items())
        if opts.sort_keys:
            items=sorted(items, key=lambda kv: kv[0])
        if opts.compact:
            parts=[]
            for k,val in items:
                parts.append(wrap(key_c, escape_string(k,opts.ascii))+wrap(obj_c,":")+render_value(val,opts,level+1,colors))
            inner=(wrap(obj_c,",")).join(parts)
            return wrap(obj_c,"{")+inner+wrap(obj_c,"}")
        if len(items)==0:
            return wrap(obj_c,"{")+wrap(obj_c,"}")
        indent_str=get_indent(opts, level+1)
        base_indent=get_indent(opts, level)
        s=wrap(obj_c,"{")+"\n"
        for i,(k,val) in enumerate(items):
            s+=indent_str+wrap(key_c, escape_string(k,opts.ascii))+wrap(obj_c,":")+" "+render_value(val,opts,level+1,colors)
            if i<len(items)-1:
                s+=wrap(obj_c,",")
            s+="\n"
        s+=base_indent+wrap(obj_c,"}")
        return s
    return "null"

def compact_json(v):
    opts=OutputOpts(); opts.compact=True
    return render_value(v, opts)

def describe_value(v):
    # for errors: type (value)
    t=type_name(v)
    if t=="string":
        return f'string ({escape_string(v, False)})'
    if t=="number":
        return f'number ({format_num(v)})'
    if t=="boolean":
        return f'boolean ({"true" if v else "false"})'
    if t=="null":
        return 'null (null)'
    if t=="array":
        return f'array ({compact_json(v)})'
    if t=="object":
        return f'object ({compact_json(v)})'
    return t

def describe_plain(v):
    # e.g. Cannot use X as object key: type (value) same as above except?
    return describe_value(v)

