class JQError(Exception):
    def __init__(self, message, value=None, not_string=False):
        super().__init__(message)
        self.message=message
        # value to be caught: if value is None (?) distinguish
        self.catch_value=value  # if None special handling in raise sites
        self.not_string=not_string
    def catch_val(self):
        if self.catch_value is not None or hasattr(self,'_catch_set'):
            return self.catch_value
        return self.message

