                            j+=1
                    name=src[p+1:j]
                    self.tokens.append(Token('VAR',name,p,j)); self.pos=j; continue
                else:
                    self.tokens.append(Token('INVALID','$',p,p+1)); self.pos+=1; continue
            if ch=='@':
                # format: @ + ident
                if p+1<self.end and (src[p+1].isalpha() or src[p+1]=='_'):
                    j=p+1
                    while j<self.end and (src[j].isalnum() or src[j]=='_'):
                        j+=1
                    name=src[p+1:j]
                    self.tokens.append(Token('FORMAT',name,p,j)); self.pos=j; continue
                else:
                    self.tokens.append(Token('INVALID','@',p,p+1)); self.pos+=1; continue
            if ch.isalpha() or ch=='_':
                j=p
                while j<self.end and (src[j].isalnum() or src[j]=='_'):
                    j+=1
                # namespace :: segments (no spaces)
                while src.startswith('::', j) and j+2<self.end and (src[j+2].isalpha() or src[j+2]=='_'):
                    j+=2
                    while j<self.end and (src[j].isalnum() or src[j]=='_'):
                        j+=1
                name=src[p:j]
                self.tokens.append(Token('IDENT',name,p,j)); self.pos=j; continue
            # operators/punct two char
            two=src[p:p+2]
            if two in ('==','!=','<=','>=','|=','+=','-=','*=','/=','%='):
                self.tokens.append(Token(two,two,p,p+2)); self.pos+=2; continue
            if ch in '|,;:()[]{}?+-*/%<>=':
                self.tokens.append(Token(ch,ch,p,p+1)); self.pos+=1; continue
            # invalid char
            self.tokens.append(Token('INVALID',ch,p,p+1)); self.pos+=1; continue
        self.tokens.append(Token('EOF',None,self.pos,self.pos))
        return self.tokens
    def lex_number(self):
        src=self.src; p=self.pos
        m=re.match(r'(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?', src[p:self.end])
        txt=m.group(0)
        self.pos=p+len(txt)
        return Token('NUMBER', num_from_literal(txt), p, self.pos)
    def find_string_end(self, start):
        # start at opening quote, return index after closing quote, handling escapes and interpolation nesting
        src=self.src; i=start+1
        while i<self.end:
            ch=src[i]
            if ch=='\\':
                if i+1<self.end and src[i+1]=='(':
                    # interpolation: find matching )
                    endp=self.find_paren_end(i+2)
                    i=endp+1
                    continue
                else:
                    i+=2; continue
            if ch=='"':
                return i+1
            i+=1
        return i # EOF
    def find_paren_end(self, start):
        # start after \( , depth 1, return index of matching )
        src=self.src; i=start; depth=1
        while i<self.end:
            ch=src[i]
            if ch=='"':
                i=self.find_string_end(i); continue
            if ch=='#':
                # comment to nl (unlikely)
                while i<self.end and src[i]!='\n': i+=1
                continue
            if ch=='(':
                depth+=1; i+=1; continue
            if ch==')':
                depth-=1
                if depth==0:
                    return i
                i+=1; continue
            i+=1
        return i
    def lex_string(self):
        src=self.src; p=self.pos
        # scan building parts, also validate escapes later in parse? For lexer, collect raw parts
        i=p+1
        parts=[]
        buf=[]
        errors=[]
        while i<self.end:
            ch=src[i]
            if ch=='"':
                i+=1
                break
            if ch=='\\':
                if i+1<self.end and src[i+1]=='(':
                    if buf:
                        parts.append(('text_raw',''.join(buf))); buf=[]
                    endp=self.find_paren_end(i+2)
                    inner_start=i+2; inner_end=endp
                    # lex inner
                    sub=Lexer(src, self.filename, inner_start, inner_end)
                    subtokens=sub.tokenize()
                    parts.append(('expr', subtokens, inner_start, inner_end))
                    i=endp+1
                    continue
                else:
                    # escape sequence: keep raw 2+ chars in buffer for decoding later
                    if i+1<self.end:
                        if src[i+1]=='u':
                            # 4 hex maybe up to
                            buf.append(src[i:i+6]); i+=6
                        else:
                            buf.append(src[i:i+2]); i+=2
                    else:
                        buf.append(ch); i+=1
                    continue
            else:
                buf.append(ch); i+=1
        else:
            # unterminated, create token up to end
            pass
        if buf:
            parts.append(('text_raw',''.join(buf)))
        token=Token('STRING', parts, p, i)
        self.pos=i
        return token

def decode_string_parts(token, parser):
    # parts: list of nodes pieces: ('text', str) or ('expr', node)
    # may raise CompileError via parser special errors for invalid escapes/surrogates
    out=[]
    for part in token.value:
        if part[0]=='text_raw':
            raw=part[1]
            s=decode_raw_string(raw, token, parser)
            out.append(('text', s))
        else:
            _, subtokens, istart, iend = part
            subparser=Parser(subtokens, parser.src, parser.filename)
            node=subparser.parse_expr()
            subparser.expect_eof_for_interp()
            out.append(('expr', node))
    return out

def decode_raw_string(raw, token, parser):
    res=[]
    i=0
    while i<len(raw):
        ch=raw[i]
        if ch!='\\':
            res.append(ch); i+=1; continue
        # backslash
        if i+1>=len(raw):
            # invalid
            parser.raise_string_error("Invalid escape", token)
            res.append('\\'); i+=1; continue
        esc=raw[i+1]
        if esc=='"': res.append('"'); i+=2
        elif esc=='\\': res.append('\\'); i+=2
        elif esc=='/': res.append('/'); i+=2
        elif esc=='b': res.append('\b'); i+=2
        elif esc=='f': res.append('\f'); i+=2
        elif esc=='n': res.append('\n'); i+=2
        elif esc=='r': res.append('\r'); i+=2
        elif esc=='t': res.append('\t'); i+=2
        elif esc=='u':
            hexs=raw[i+2:i+6]
            if len(hexs)<4 or not re.fullmatch(r'[0-9a-fA-F]{4}', hexs):
                # compile error invalid \u ?
                parser.raise_string_error("Invalid \\uXXXX escape", token, kind='u_invalid')
                i+=2; continue
            code=int(hexs,16)
            if 0xD800<=code<=0xDBFF:
                # check following \u
                if raw[i+6:i+8]=='\\u':
                    hex2=raw[i+8:i+12]
                    if re.fullmatch(r'[0-9a-fA-F]{4}', hex2 or ''):
                        code2=int(hex2,16)
                        if 0xDC00<=code2<=0xDFFF:
                            res.append(chr(0x10000+((code-0xD800)<<10)+(code2-0xDC00)))
                            i+=12; continue
                parser.raise_string_error("Invalid \\uXXXX\\uXXXX surrogate pair escape", token, kind='surrogate')
                i+=6; continue
            elif 0xDC00<=code<=0xDFFF:
                parser.raise_string_error("Invalid \\uXXXX\\uXXXX surrogate pair escape", token, kind='surrogate')
                i+=6; continue
            else:
                res.append(chr(code)); i+=6; continue
        else:
            parser.raise_string_error("Invalid escape", token, kind='escape')
            i+=2; continue
    return ''.join(res)

# ---------- Parser ----------
class Node:
    __slots__=('kind','pos','end','a','b','c','d','e')
    def __init__(self, kind, pos=0,end=0,a=None,b=None,c=None,d=None,e=None):
        self.kind=kind; self.pos=pos; self.end=end; self.a=a; self.b=b; self.c=c; self.d=d; self.e=e
    def __repr__(self):
        return f"N({self.kind},{self.a!r},{self.b!r})"

def make_node(kind,pos,end,a=None,b=None,c=None,d=None,e=None):
    return Node(kind,pos,end,a,b,c,d,e)

class Parser:
    def __init__(self, tokens, src, filename):
        self.tokens=tokens; self.src=src; self.filename=filename
        self.i=0
        self.is_top=False
        self.compile_errors=[] # special string errors etc collected? parser raises ParseFailure for syntax
    def peek(self, offset=0):
        idx=min(self.i+offset, len(self.tokens)-1)
        return self.tokens[idx]
    def next(self):
        t=self.tokens[self.i]
        if self.i < len(self.tokens)-1:
            self.i+=1
        return t
    def at(self, typ, value=None):
        t=self.peek()
        return t.type==typ and (value is None or t.value==value)
    def at_ident(self, name):
        t=self.peek()
        return t.type=='IDENT' and t.value==name
    def consume(self, typ, value=None):
        if self.at(typ,value):
            return self.next()
        return None
    def expect(self, typ, value=None):
        if self.at(typ,value):
            return self.next()
        t=self.peek()
        raise self.syntax_error(t)
    def syntax_error(self, tok, expected=None):
        # Build generic syntax error ParseFailure; the top handler formats it
        return ParseFailure("syntax error", tok.pos, expected=expected, token_desc=self.token_name(tok))
    def token_name(self, tok):
        if tok.type=='EOF': return "end of file"
        if tok.type=='IDENT': return tok.value if tok.value in KEYWORDS else "IDENT"
        if tok.type=='VAR': return "BINDING"
        if tok.type=='FIELD': return "FIELD"
        if tok.type=='STRING': return "QQSTRING_START"
        if tok.type=='NUMBER': return "LITERAL"
        if tok.type=='FORMAT': return "FORMAT"
        if tok.type=='INVALID': return "INVALID_CHARACTER"
        if tok.type=='..': return ".."
        return f"'{tok.type}'" if len(tok.type)==1 else tok.type
    def raise_string_error(self, msg, token, kind=None):
        # raise CompileErrorList with special message format for string errors at compile time
        # For surrogate: jq message: Invalid \uXXXX\uXXXX surrogate pair escape at line X, column Y (while parsing '"..."') at <top-level>, line... 
        # We will raise ParseFailure with special msg marker and handle in top level converter
        pf=ParseFailure(msg, token.pos)
        pf.token_desc='STRING_ERROR'
        pf.string_token=token
        pf.kind=kind
        raise pf
    def expect_eof_for_interp(self):
        if not self.at('EOF'):
            raise self.syntax_error(self.peek())
    # Top parse
    def parse_top(self):
        self.is_top=True
        if self.at('EOF'):
            # empty program: jq prints usage? Actually with filter missing CLI handles. If filter string empty?
            # parser returns empty node; checker will handle top not given
            return make_node('emptyprog',0,0)
        node=self.parse_expr()
        if not self.at('EOF'):
            raise self.syntax_error(self.peek())
        return node
    # Expression entry
    def parse_expr(self):
        # directives
        if self.at_ident('def') or self.at_ident('import') or self.at_ident('include') or self.at_ident('module'):
            directive=self.parse_directive()
            # after directive, rest
            if self.at('EOF') and self.is_top:
                rest=make_node('emptyprog', self.peek().pos, self.peek().pos)
            elif self.at('EOF') or self.at(')') or self.at(']') or self.at('}'):
                # empty rest (e.g. in module handled elsewhere; in top program error will be raised by checker)
                rest=make_node('emptyprog', self.peek().pos, self.peek().pos)
            else:
                rest=self.parse_expr()
            return make_node('defscope', directive.pos, directive.end, directive, rest)
        # label handling at segment level is inside parse_pipe->parse_comma->parse_segment
        return self.parse_pipe()
    def parse_directive(self):
        if self.at_ident('module'):
            t=self.next()
            # module expr: parse_pipe (?) object
            expr=self.parse_pipe()
            self.expect(';')
            return make_node('moduledecl', t.pos, t.end, expr)
        if self.at_ident('import'):
            t=self.next()
            if not self.at('STRING'):
                raise self.syntax_error(self.peek())
            stok=self.next()
            parts=decode_string_parts(stok, self)
            # must be plain text
            name=''.join(p[1] for p in parts if p[0]=='text') if all(p[0]=='text' for p in parts) else None
            if name is None:
                raise self.syntax_error(stok)
            self.expect_ident('as')
            # alias ident or var
            if self.at('VAR'):
                vt=self.next(); alias=vt.value; is_var=True; apos=vt.pos; aend=vt.end
            elif self.at('IDENT'):
                it=self.next(); alias=it.value; is_var=False; apos=it.pos; aend=it.end
            else:
                raise self.syntax_error(self.peek())
            self.expect(';')
            return make_node('import', t.pos, aend, name, alias, is_var)
        if self.at_ident('include'):
            t=self.next()
            if not self.at('STRING'):
                raise self.syntax_error(self.peek())
            stok=self.next()
            parts=decode_string_parts(stok, self)
            name=''.join(p[1] for p in parts if p[0]=='text') if all(p[0]=='text' for p in parts) else None
            if name is None:
                raise self.syntax_error(stok)
            self.expect(';')
            return make_node('include', t.pos, t.end, name)
        if self.at_ident('def'):
            t=self.next()
            if not self.at('IDENT'):
                raise self.syntax_error(self.peek())
            nt=self.next(); name=nt.value
            params=[]
            if self.consume('('):
                while True:
                    if self.at('VAR'):
                        vt=self.next(); params.append((vt.value, True))
                    elif self.at('IDENT'):
                        it=self.next(); params.append((it.value, False))
                    else:
                        raise self.syntax_error(self.peek())
                    if self.consume(';'):
                        continue
                    break
                self.expect(')')
            self.expect(':')
            body=self.parse_expr()
            semi=self.expect(';')
            return make_node('def', t.pos, semi.end, name, params, body)
        raise self.syntax_error(self.peek())
    def expect_ident(self, name):
        if self.at_ident(name):
            return self.next()
        raise self.syntax_error(self.peek())
    # pipe level
    def parse_pipe(self):
        left=self.parse_comma()
        if self.consume('|'):
            right=self.parse_pipe()
            return make_node('pipe', left.pos, right.end, left, right)
        return left
    def parse_comma(self):
        left=self.parse_segment()
        if self.at(','):
            # comma level: continue with parse_comma (operands segment)
            self.next()
            right=self.parse_comma()
            return make_node('comma', left.pos, right.end, left, right)
        return left
    def parse_segment(self):
        # directives already handled at parse_expr entry, but a segment after pipe/comma could be def/label
        if self.at_ident('def') or self.at_ident('import') or self.at_ident('include') or self.at_ident('module'):
            # delegate to parse_expr directive handling
            return self.parse_expr()
        if self.at_ident('label'):
            t=self.next()
            if not self.at('VAR'):
                raise self.syntax_error(self.peek())
            vt=self.next()
            self.expect('|')
            body=self.parse_expr()
            return make_node('label', t.pos, body.end, vt.value, body)
        head=self.parse_assign()
        if self.at_ident('as'):
            self.next()
            patterns=self.parse_patterns()
            self.expect('|')
            body=self.parse_expr()
            return make_node('bind', head.pos, body.end, head, patterns, body)
        return head
    def parse_patterns(self):
        pats=[self.parse_pattern()]
        while self.consume('?//'):
            pats.append(self.parse_pattern())
        return pats
    def parse_pattern(self):
        if self.at('VAR'):
            t=self.next(); return make_node('pvar', t.pos,t.end, t.value)
        if self.consume('['):
            pats=[]
            if not self.at(']'):
                while True:
                    pats.append(self.parse_pattern())
                    if self.consume(','):
                        if self.at(']'): break
                        continue
                    break
            self.expect(']')
            return make_node('parray', 0,0, pats)
        if self.consume('{'):
            entries=[]
            if not self.at('}'):
                while True:
                    if self.at('VAR'):
                        vt=self.next(); entries.append( (vt.value, make_node('pvar',vt.pos,vt.end,vt.value), 'var', vt) )
                    elif self.at('IDENT'):
                        it=self.next(); key=it.value
                        if self.consume(':'):
                            sub=self.parse_pattern()
                        else:
                            sub=make_node('pvar', it.pos,it.end, key)
                        entries.append((key, sub, 'ident', it))
                    elif self.at('STRING'):
                        st=self.next(); parts=decode_string_parts(st, self); keynode=make_node('string', st.pos,st.end, parts)
                        self.expect(':')
                        sub=self.parse_pattern()
                        entries.append((keynode, sub, 'string', st))
                    elif self.consume('('):
                        expr=self.parse_expr(); rp=self.expect(')')
                        self.expect(':')
                        sub=self.parse_pattern()
                        entries.append((expr, sub, 'expr', rp))
                    else:
                        raise self.syntax_error(self.peek())
                    if self.consume(','):
                        if self.at('}'): break
                        continue
                    break
            self.expect('}')
            return make_node('pobject',0,0,entries)
        raise self.syntax_error(self.peek())
    # assignment
    def parse_assign(self):
        left=self.parse_alt()
        t=self.peek()
        if t.type in ('=','|=','+=','-=','*=','/=','%=','//='):
            op=self.next()
            right=self.parse_alt()
            return make_node('assign', left.pos, right.end, left, op.type, right)
        return left
    def parse_alt(self):
        left=self.parse_or()
        while self.consume('//'):
            right=self.parse_or()
            left=make_node('alt', left.pos, right.end, left, right)
        return left
    def parse_or(self):
        left=self.parse_and()
        while self.at_ident('or'):
            self.next(); right=self.parse_and(); left=make_node('or',left.pos,right.end,left,right)
        return left
    def parse_and(self):
        left=self.parse_cmp()
        while self.at_ident('and'):
            self.next(); right=self.parse_cmp(); left=make_node('and',left.pos,right.end,left,right)
        return left
    def parse_cmp(self):
        left=self.parse_add()
        t=self.peek()
        if t.type in ('==','!=','<','<=','>','>='):
            op=self.next(); right=self.parse_add()
            return make_node('cmp', left.pos,right.end,left,op.type,right)
        return left
    def parse_add(self):
        left=self.parse_mul()
        while self.peek().type in ('+','-'):
            op=self.next(); right=self.parse_mul(); left=make_node('binop',left.pos,right.end,left,op.type,right)
        return left
    def parse_mul(self):
        left=self.parse_unary()
        while self.peek().type in ('*','/','%'):
            op=self.next(); right=self.parse_unary(); left=make_node('binop',left.pos,right.end,left,op.type,right)
        return left
    def parse_unary(self):
        if self.at('-'):
            t=self.next()
            operand=self.parse_unary()
            return make_node('neg', t.pos, operand.end, operand)
        return self.parse_term()
    def parse_term(self):
        t=self.peek()
        node=None
        if t.type=='FIELD':
            self.next()
            node=make_node('field', t.pos,t.end, make_node('identity',t.pos,t.pos), t.value)
        elif t.type=='.':
            self.next(); node=make_node('identity', t.pos,t.end)
        elif t.type=='..':
            self.next(); node=make_node('recurse_down', t.pos,t.end)
        elif t.type=='NUMBER':
            self.next(); node=make_node('literal', t.pos,t.end, t.value)
        elif t.type=='STRING':
            self.next(); parts=decode_string_parts(t, self); node=make_node('string', t.pos,t.end, parts)
        elif t.type=='VAR':
            self.next(); node=make_node('var', t.pos,t.end, t.value)
        elif t.type=='FORMAT':
            self.next()
            fmtarg=None
            if self.at('STRING'):
                st=self.next(); parts=decode_string_parts(st, self); fmtarg=make_node('string', st.pos,st.end, parts)
            node=make_node('format', t.pos, (fmtarg.end if fmtarg else t.end), t.value, fmtarg)
        elif t.type=='(':
            self.next(); inner=self.parse_expr(); rp=self.expect(')')
            node=make_node('paren', t.pos, rp.end, inner)
        elif t.type=='[':
            self.next()
            if self.consume(']'):
                node=make_node('arraylit', t.pos, t.end+1)
            else:
                inner=self.parse_expr(); rb=self.expect(']')
                node=make_node('arraybuild', t.pos, rb.end, inner)
        elif t.type=='{':
            node=self.parse_object()
        elif t.type=='IDENT':
            name=t.value
            if name=='null':
                self.next(); node=make_node('literal', t.pos,t.end, None)
            elif name=='true':
                self.next(); node=make_node('literal', t.pos,t.end, True)
            elif name=='false':
                self.next(); node=make_node('literal', t.pos,t.end, False)
            elif name=='if':
                node=self.parse_if()
            elif name=='try':
                node=self.parse_try()
            elif name=='reduce':
                node=self.parse_reduce_for('reduce')
            elif name=='foreach':
                node=self.parse_reduce_for('foreach')
            elif name=='label':
                # label not a term (for try case) - but if reached here, treat as segment? raise
                raise self.syntax_error(t)
            elif name=='break':
                self.next()
                if not self.at('VAR'):
                    raise self.syntax_error(self.peek())
                vt=self.next(); node=make_node('break', t.pos, vt.end, vt.value)
            elif name in ('then','elif','else','end','catch','as','def','import','include','module','and','or'):
                raise self.syntax_error(t)
            else:
                # function call
                self.next()
                args=[]
                if self.consume('('):
                    if not self.at(')'):
                        while True:
                            args.append(self.parse_expr())
                            if self.consume(';'):
                                continue
                            break
                    self.expect(')')
                node=make_node('call', t.pos, t.end, name, args)
        else:
            raise self.syntax_error(t)
        # suffixes
        node=self.apply_suffixes(node)
        return node
    def apply_suffixes(self, node):
        while True:
            if self.at('FIELD'):
                ft=self.next()
                node=make_node('field', node.pos, ft.end, node, ft.value)
                continue
            if self.at('.'):
                # '.' followed by [ or STRING handled by lexer: '.' then '[' token or STRING token
                # peek next
                nxt=self.peek(1)
                if nxt.type=='[' or nxt.type=='STRING':
                    self.next() # consume '.'
                    continue # loop will handle [ or STRING suffix below (STRING not handled as suffix here; handle separately)
                else:
                    break
            if self.at('STRING') and getattr(node,'_dot_pending',False):
                pass
            # string suffix after dot: This arises when previous loop consumed '.' and next is STRING
            # But our loop doesn't track. Handle: if preceding char was '.'? Approach: if token STRING and node just had dot consumed, we would have looped.
            # Instead, above '.' handling: when '.' + STRING, we need to directly consume string
            # That logic is implemented below in alternative check: we already consumed '.' and continued, now STRING token should be treated
            if self.at('STRING') and self._last_dot_consumed:
                st=self.next(); parts=decode_string_parts(st,self); skey=make_node('string',st.pos,st.end,parts)
                node=make_node('index', node.pos, st.end, node, skey)
                self._last_dot_consumed=False
                continue
            if self.at('['):
                bt=self.next()
                if self.consume(']'):
                    node=make_node('iterate', node.pos, bt.end, node)
                    continue
                # slice or index
                # check if ':' immediately
                if self.at(':'):
                    self.next()
                    endexpr=None
