# ---------- Source location helpers ----------
def source_line_col(src, pos):
    if src is None:
        return 1,1,""
    upto=src[:pos]
    line=upto.count('\n')+1
    last=upto.rfind('\n')
    col=pos-last if last>=0 else pos+1  # 1-indexed column of char at pos (jq: position??)
    # jq column appears to be 1-indexed?
    lines=src.split('\n')
    text=lines[line-1] if line-1 < len(lines) else ""
    return line,col,text

class CompileIssue:
    def __init__(self, msg, src=None, filename="<top-level>", pos=0, end=None, no_loc=False):
        self.msg=msg; self.src=src; self.filename=filename; self.pos=pos; self.end=end; self.no_loc=no_loc

def format_compile_issues(issues):
    out=[]
    for iss in issues:
        if iss.no_loc:
            out.append(f"jq: error: {iss.msg}\n\n")
        else:
            line,col,text=source_line_col(iss.src or "", iss.pos)
            span_len=max(1, (iss.end-iss.pos) if iss.end is not None and iss.end>iss.pos else 1)
            # caret indent: 4 spaces + (col-1)
            out.append(f"jq: error: {iss.msg} at {iss.filename}, line {line}, column {col}:\n    {text}\n    {' '*(col-1)}{'^'*span_len}\n")
    n=len(issues)
    out.append(f"jq: {n} compile error{'s' if n!=1 else ''}\n")
    return ''.join(out)

# constant evaluation for object keys
def const_eval(node):
    # returns (True, value) or (False, None)
    try:
        if node.kind=='literal':
            return True, node.a
        if node.kind=='paren':
            return const_eval(node.a)
        if node.kind=='string':
            # all text
            s=''
            for typ,val in node.a:
                if typ!='text': return False,None
                s+=val
            return True,s
        if node.kind=='stringconst':
            return True, node.a
        if node.kind=='arraylit':
            return True,[]
        if node.kind=='arraybuild':
            ok,v=const_eval(node.a)
            # arraybuild with a generator that is const comma?
            # handle comma in helper
            vals=const_eval_multi(node.a)
            if vals is not None:
                return True, vals
            return False,None
        if node.kind=='objectlit':
            obj={}
            for keynode, valnode, kk in node.a:
                okk,kv=const_eval(keynode)
                if not okk or not isinstance(kv,str): return False,None
                vals=const_eval_multi(valnode)
                if vals is None or len(vals)!=1: return False,None
                obj[kv]=vals[0]
            return True,obj
        if node.kind=='comma':
            return False,None
        if node.kind=='neg':
            ok,v=const_eval(node.a)
            if ok and isinstance(v,Num):
                return True, neg_num(v)
            return False,None
        if node.kind=='binop':
            # handle + etc via evaluator arithmetic on const values
            lv=const_eval_multi(node.a); rv=const_eval_multi(node.c)
            # note node structure binop: a=left,b=op,c=right? Check parser: make_node('binop',...,left,op,right) => a left,b op,c right
            if lv is None or rv is None or len(lv)!=1 or len(rv)!=1: return False,None
            return True, do_binary_op(node.b, lv[0], rv[0])
        if node.kind=='pipe':
            lv=const_eval_multi(node.a)
            if lv is None: return False,None
            # pipe const: evaluate right for each? simplify only if right const independent
            ok,v=const_eval(node.b)
            if ok: return True,v
            return False,None
    except Exception:
        return False,None
    return False,None

def const_eval_multi(node):
    if node is None: return None
    if node.kind=='comma':
        left=const_eval_multi(node.a); right=const_eval_multi(node.b)
        if left is None or right is None: return None
        return left+right
    ok,v=const_eval(node)
    if ok: return [v]
    return None

def neg_num(v):
    if isinstance(v, Num):
        if v.dec is not None:
            return Num(-v.v, -v.dec)
        return Num(-v.v, None)
    raise JQError(f"{describe_value(v)} cannot be negated")

