            if name not in scope.vars:
                self.issue(f"${name} is not defined", node)
            return
        if k=='format':
            if node.b: self.check(node.b, scope)
            return
        if k=='paren':
            self.check(node.a, scope); return
        if k=='arraybuild':
            self.check(node.a, scope); return
        if k=='objectlit':
            for keynode, valnode, kk in node.a:
                # key check
                if kk=='var':
                    # $var as key: need var defined? {$a:1} gave $a is not defined
                    if keynode.a not in scope.vars and keynode.a!='__loc__':
