                            self.issue(f"Cannot use {describe_value(val)} as object key", inner)
                self.check(valnode, scope)
            return
        if k=='call':
            name=node.a; args=node.b
            sig=(name, len(args))
            if sig not in scope.funcs:
                self.issue(f"{name}/{len(args)} is not defined", node)
            for a in args: self.check(a, scope)
            return
        if k in ('pipe','comma','alt','or','and'):
            self.check(node.a, scope); self.check(node.b, scope); return
        if k=='bind':
            self.check(node.a, scope)
            newscope=scope.clone()
            for pat in node.b:
                for v in pattern_vars(pat): newscope.vars.add(v)
                self.check_pattern(pat, scope)
            self.check(node.c, newscope); return
        if k=='assign':
            self.check(node.a, scope); self.check(node.c, scope); return
        if k in ('cmp','binop'):
            self.check(node.a, scope); self.check(node.c, scope); return
        if k=='neg' or k=='optional':
            self.check(node.a, scope); return
        if k=='if':
            for cond,branch in node.a:
                self.check(cond, scope); self.check(branch, scope)
            if node.b: self.check(node.b, scope)
            return
        if k=='try':
            self.check(node.a, scope)
            if node.b: self.check(node.b, scope)
            return
        if k=='reduce':
            self.check(node.a, scope)
            newscope=scope.clone()
            for pat in node.b:
                for v in pattern_vars(pat): newscope.vars.add(v)
                self.check_pattern(pat, scope)
            self.check(node.c, scope) # init in outer
            self.check(node.d, newscope); return
        if k=='foreach':
            self.check(node.a, scope)
            newscope=scope.clone()
            for pat in node.b:
                for v in pattern_vars(pat): newscope.vars.add(v)
                self.check_pattern(pat, scope)
            self.check(node.c, scope)
            self.check(node.d, newscope)
            if node.e: self.check(node.e, newscope)
            return
        if k=='label':
            newscope=scope.clone(); newscope.vars.add("*label-"+node.a)
            self.check(node.b, newscope); return
        if k=='break':
            internal="*label-"+node.a
            if internal not in scope.vars:
                # message as $*label-x
                self.issue(f"$*label-{node.a} is not defined", node)
            return
        # fallback generic recurse Node fields
        for attr in ('a','b','c','d','e'):
            v=getattr(node, attr, None)
            if isinstance(v, Node): self.check(v, scope)
            elif isinstance(v,list):
                for item in v:
                    if isinstance(item,Node): self.check(item,scope)
                    elif isinstance(item,tuple):
                        for sub in item:
                            if isinstance(sub,Node): self.check(sub,scope)
        return
    def check_pattern(self, pat, scope):
        if pat.kind=='pvar': return
        if pat.kind=='parray':
            for p in pat.a: self.check_pattern(p,scope)
            return
        if pat.kind=='pobject':
            for entry in pat.a:
                keything, sub, ktype, tok = entry
                if isinstance(keything, Node):
                    self.check(keything, scope)
                self.check_pattern(sub, scope)
            return

