def eval_if_chain(branches, idx, else_node, inp, env):
    if idx>=len(branches):
        if else_node is not None:
            yield from eval_node(else_node, inp, env)
        return
    cond,branch=branches[idx]
    for cv in eval_node(cond, inp, env):
        if truthy(cv):
            yield from eval_node(branch, inp, env)
        else:
            yield from eval_if_chain(branches, idx+1, else_node, inp, env)

def eval_string_node(node, inp, env):
    # parts generation cartesian: text and expr values combine
    parts=node.a
    # iterative
    def rec(i, current):
        if i>=len(parts):
            yield current; return
        typ,val=parts[i]
        if typ=='text':
            yield from rec(i+1, current+val)
        else:
            for v in eval_node(val, inp, env):
                # interpolation converts to string: if string raw, if number etc tostring, objects json
                s=jq_tostring(v)
                yield from rec(i+1, current+s)
    yield from rec(0,"")

