def eval_object(node, inp, env):
    entries=node.a
    # each entry can generate multiple objects due to key/value generators: cartesian over entries sequentially
    def rec(i, current):
        if i>=len(entries):
            yield dict(current); return
        keynode, valnode, kk = entries[i]
        # keys
        if kk=='var':
            keys=[keynode.a]  # stringconst name
        elif keynode.kind=='stringconst':
            keys=[keynode.a]
        else:
            keys=[]
            for kv in eval_node(keynode, inp, env):
                if not isinstance(kv,str):
                    raise error_jq(f"Cannot use {describe_value(kv)} as object key")
                keys.append(kv)
        for kstr in keys:
            for vv in eval_node(valnode, inp, env):
