def bind_pattern(pat, value, orig_inp, env):
    # yields new envs
    if pat.kind=='pvar':
        new=env.clone(); new.vars[pat.a]=value; yield new; return
    if pat.kind=='parray':
        # index value by numbers (this may error)
        subvalues=[]
        for i,sub in enumerate(pat.a):
            ev=index_value(value, num_from_py_int(i))
            subvalues.append((sub,ev))
        # combine
        def rec(idx, curenv):
            if idx>=len(subvalues):
                yield curenv; return
            sub,ev=subvalues[idx]
            for e2 in bind_pattern(sub, ev, orig_inp, curenv):
                yield from rec(idx+1, e2)
        yield from rec(0, env); return
    if pat.kind=='pobject':
        # entries: list of tuples (keything, subpattern, type, token)
        # compute for each entry: possible (subpattern, subvalue) options (key experiments may yield multiple)
        entries_options=[]
        for entry in pat.a:
            keything, subpat, ktype, tok = entry
            opts=[]
            if ktype=='var':
                kstr=keything # name string
                ev=index_value(value, kstr)
                opts.append(ev)
            elif ktype=='ident':
                kstr=keything
                ev=index_value(value, kstr)
                opts.append(ev)
            elif ktype=='string':
                # keything is string node
                for kstr in eval_node(keything, value, env):
                    if not isinstance(kstr,str):
                        raise error_jq(f"Cannot use {describe_value(kstr)} as object key")
                    ev=index_value(value, kstr)
                    opts.append(ev)
            elif ktype=='expr':
                for kstr in eval_node(keything, value, env):
                    if not isinstance(kstr,str):
                        raise error_jq(f"Cannot use {describe_value(kstr)} as object key")
                    ev=index_value(value, kstr)
                    opts.append(ev)
            elif isinstance(keything, Node):
                for kstr in eval_node(keything, value, env):
                    if not isinstance(kstr,str):
                        raise error_jq(f"Cannot use {describe_value(kstr)} as object key")
                    ev=index_value(value, kstr)
                    opts.append(ev)
            else:
                # string name
                ev=index_value(value, keything); opts.append(ev)
            entries_options.append((subpat, opts))
        def rec2(idx, curenv):
            if idx>=len(entries_options):
                yield curenv; return
            subpat, opts = entries_options[idx]
            for ev in opts:
                for e2 in bind_pattern(subpat, ev, orig_inp, curenv):
                    yield from rec2(idx+1, e2)
        yield from rec2(0, env); return
    raise error_jq("invalid pattern")

def eval_reduce(node, inp, env, is_foreach):
    # node: reduce/foreach
    source=node.a; patterns=node.b; init_node=node.c; update_node=node.d; extract_node=node.e if node.kind=='foreach' else None
    # init values
    for init_val in eval_node(init_node, inp, env):
        # iterate source values sequentially, updating state; source outputs are evaluated once (list to allow state progression)
        # But source could be infinite (repeat) with foreach/limit outside - need lazy.
        # We'll iterate lazily.
        state=init_val
        src_iter=iter(lambda: None, None) # placeholder
        # implement generator manual
        source_gen=eval_node(source, inp, env)
        # foreach: for each state after update, emit extract/state
        # reduce: after all, emit final
        # To handle pattern alternatives: bind_pattern may fail => try alternatives
        def process_from(gen, current_state):
            # generator recursion using yield from inside try for foreach emission is complex
            # We'll implement iterative pulling in outer function using recursion via helper generator
            yield from _reduce_iter(gen, current_state, patterns, update_node, extract_node, inp, env, is_foreach)
        if is_foreach:
            yield from process_from(source_gen, state)
        else:
            # reduce: _reduce_iter with is_foreach=False will yield final state once at end
            yield from process_from(source_gen, state)
    return

def _reduce_iter(source_gen, state, patterns, update_node, extract_node, orig_inp, env, is_foreach):
    try:
        src_val=next(source_gen)
    except StopIteration:
        if not is_foreach:
            yield state
        return
    # bind src_val to patterns alternatives
    envs=None; last_err=None
    for pat in patterns:
        try:
            envs=list(bind_pattern(pat, src_val, orig_inp, env))
            break
        except JQError as e:
            last_err=e; continue
    if envs is None:
        raise last_err
    for newenv in envs:
        # update can produce multiple states: each becomes a branch
        for new_state in eval_node(update_node, state, newenv):
            if is_foreach:
                if extract_node is not None:
                    for out in eval_node(extract_node, new_state, newenv):
                        yield out
                else:
                    yield new_state
                # continue with remaining source items: need to clone source_gen? Generators cannot be cloned.
                # This branching with multiple update outputs is rare; we continue using same generator (consumes rest for first branch only)
                yield from _reduce_iter(source_gen, new_state, patterns, update_node, extract_node, orig_inp, env, is_foreach)
            else:
                yield from _reduce_iter(source_gen, new_state, patterns, update_node, extract_node, orig_inp, env, is_foreach)

# ----- Path evaluation / assignment -----
def eval_path_expr(node, inp, env):
    # yields lists (paths)
    # Try tracked interpretation for common cases; fallback to special logic
    # Use recursive analysis:
    k=node.kind
    if k=='identity':
        yield []; return
    if k=='paren':
        yield from eval_path_expr(node.a, inp, env); return
    if k=='field':
        # base path + [name]
        for p in eval_path_expr(node.a, inp, env):
            yield p+[node.b]
        return
    if k=='index':
        # base paths, key expr evaluated against inp (original)
        for p in eval_path_expr(node.a, inp, env):
            for key in eval_node(node.b, inp, env):
                if isinstance(key, (str,Num)):
                    yield p+[key]
                elif isinstance(key, dict):
                    yield p+[key]
                else:
                    # key is e.g. array: invalid path?
                    raise error_jq(f"Invalid path expression with result {compact_json(key)}")
        return
    if k=='slice':
        for p in eval_path_expr(node.a, inp, env):
            starts=[None] if node.b is None else list(eval_node(node.b, inp, env))
            ends=[None] if node.c is None else list(eval_node(node.c, inp, env))
            for s in starts:
                for e in ends:
                    yield p+[{"start":s,"end":e}]
        return
    if k=='iterate':
        # .[] - expand based on value at path
        # Need actual value at paths to enumerate keys
        for p in eval_path_expr(node.a, inp, env):
            val=getpath_value(inp, p) if False else None
            # get value from inp using path p (but p may be relative to inp: eval_path called with inp as root of expr)
            # Determine root value: we need a helper that gets value at p from the original inp of this call.
            # However nested pipes change inp; our recursion for pipe handles that.
            base_val=_get_path_from_root(inp, p)
            if isinstance(base_val, list):
                for i in range(len(base_val)):
                    yield p+[num_from_py_int(i)]
            elif isinstance(base_val, dict):
                for kk in base_val.keys():
                    yield p+[kk]
            else:
                raise error_jq(f"Cannot iterate over {describe_value(base_val)}")
        return
    if k=='pipe':
        for p1 in eval_path_expr(node.a, inp, env):
            subval=_get_path_from_root(inp, p1)
            for p2 in eval_path_expr(node.b, subval, env):
                yield p1+p2
