        yield from eval_path_expr(node.a, inp, env)
        yield from eval_path_expr(node.b, inp, env)
        return
    if k=='if':
        for cond,branch in node.a:
            # evaluate condition against inp: if any truthy... need per output logic like normal if but path branches
            # Implement iteration over condition outputs
            def _if_path(branches, idx, else_node):
                if idx>=len(branches):
                    if else_node is not None:
                        yield from eval_path_expr(else_node, inp, env)
                    return
                c,b=branches[idx]
                for cv in eval_node(c, inp, env):
                    if truthy(cv):
                        yield from eval_path_expr(b, inp, env)
                    else:
                        yield from _if_path(branches, idx+1, else_node)
            yield from _if_path(node.a,0,node.b); return
