            yield from eval_path_expr(node.b, inp, env)
        return
    if k=='optional':
        try:
            yield from eval_path_expr(node.a, inp, env)
        except JQError:
            return
        return
    if k=='try':
        try:
            yield from eval_path_expr(node.a, inp, env)
        except JQError as e:
            if node.b:
                yield from eval_path_expr(node.b, get_catch_value(e), env)
        return
    if k=='recurse_down':
        yield []; return
    if k=='call':
        # special path-capable builtins: first, last, recurse, etc are handled via tracked fallback? For now, examine some
        if node.a=='getpath' and len(node.b)==1:
