            for pv in eval_node(node.b[0], inp, env):
                if isinstance(pv,list):
                    yield pv
                else:
                    raise error_jq("Path must be specified as an array")
            return
        # User or builtin functions: try evaluating function as normal and see if it's tracked? Not a path.
        # Fallback: evaluate call normally and raise invalid path with result
        vals=list(eval_node(node, inp, env))
        # If call is something like 'paths' ??? path(paths) yields empty in jq because paths yields paths but path of that ??? It returned empty.
        # To mimic, if function name in ('paths',): return
        # Generic: raise invalid path with first result
        if vals:
            raise error_jq(f"Invalid path expression with result {compact_json(vals[0])}")
        return
    if k=='bind':
        # . as $x | path-body: evaluate source, bind, then path of body against source value
        for src_val in eval_node(node.a, inp, env):
            for pat in node.b:
                try:
                    envs=list(bind_pattern(pat, src_val, inp, env))
