    vals=[]
    try:
        for v in eval_node(node, inp, env):
            vals.append(v); break
    except JQError:
        raise
    if vals:
        raise error_jq(f"Invalid path expression with result {compact_json(vals[0])}")
    # no output => no path
    return

def _get_path_from_root(root, path):
    cur=root
    for comp in path:
        if isinstance(comp, dict) and 'start' in comp:
            cur=slice_value(cur, comp.get('start'), comp.get('end'))
        else:
            cur=index_value(cur, comp)
    return cur

