def _reduce_iter(source_gen, state, patterns, update_node, extract_node, orig_inp, env, is_foreach):
    try:
        src_val=next(source_gen)
    except StopIteration:
        if not is_foreach:
            yield state
        return
    # bind src_val to patterns alternatives
    envs=None; last_err=None
    for pat in patterns:
        try:
            envs=list(bind_pattern(pat, src_val, orig_inp, env))
            break
        except JQError as e:
            last_err=e; continue
    if envs is None:
        raise last_err
    for newenv in envs:
        # update can produce multiple states: each becomes a branch
        for new_state in eval_node(update_node, state, newenv):
            if is_foreach:
                if extract_node is not None:
                    for out in eval_node(extract_node, new_state, newenv):
