# Add Parser method for modules (monkey-patch style appended)
def _parser_parse_module(self):
    meta=None
    directives=[]
    if self.at_ident('module'):
        d=self.parse_directive(); meta=d.a; directives.append(d)
    while self.at_ident('def') or self.at_ident('import') or self.at_ident('include'):
        directives.append(self.parse_directive())
    if not self.at('EOF'):
        # Module has main expression
        raise CompileErrorList([CompileIssue('jq: error: library should only have function definitions, not a main expression', None, self.filename, 0, no_loc=True)])
    return meta, directives
Parser.parse_module=_parser_parse_module

# ---------- Modules ----------
