def expand_search_entry(entry):
    e=entry
    if e=="~" or e.startswith("~/"):
        home=os.environ.get("HOME","")
        e=home+e[1:] if home else e
    e=e.replace("$ORIGIN", CTX.jq_origin)
    return e

def resolve_module(relpath, is_data):
    # returns path or raises ModuleNotFound / compile relative traversal
    # Check traversal: any '..' path component
    parts=relpath.split('/')
    if '..' in parts:
        raise ModuleNotFoundIssue(CompileIssue(f"Relative paths to modules may not traverse to parent directories ({relpath})", None, "<top-level>",0,no_loc=True))
    # strip leading ./ components
    while parts and parts[0]=='.':
        parts=parts[1:]
    rel='/'.join(parts)
    candidates=[]
    for entry in get_search_list_values():
        base=expand_search_entry(entry)
