        if not os.path.isdir(base):
            continue
        if is_data:
            candidates.append(os.path.join(base, rel+".json"))
            # also (?) json files could be .jq? no
        else:
            candidates.append(os.path.join(base, rel+".jq"))
    for cand in candidates:
        if os.path.isfile(cand):
            return cand
    raise ModuleNotFoundIssue(CompileIssue(f"module not found: {relpath}", None, "<top-level>",0,no_loc=True))

def load_module_info_by_path(path):
    if path in CTX.module_cache:
        return CTX.module_cache[path]
    info=ModuleInfo(); info.path=path; info.filename=path
