        try:
            vals=parse_json_text_all(text)
            info.data=[v for v,_ln in vals]
        except JSONParseError as e:
            raise CompileErrorList([CompileIssue(e.msg, None, path,0,no_loc=True)])
        info.defs_list=[]; info.deps_list=[]
        return info
    with open(path,'r',encoding='utf-8',errors='surrogateescape') as f:
        text=f.read()
    info.src=text
    lexer=Lexer(text, path)
    try:
        tokens=lexer.tokenize()
        parser=Parser(tokens, text, path)
        meta, directives=parser.parse_module()
        info.meta_node=meta; info.directives=directives
    except ParseFailure as pf:
        raise convert_parse_failure(pf, text, path)
    # compute defs/deps lists (for modulemeta)
    defs=[]; deps=[]
    for d in directives:
        if d.kind=='def':
            defs.append(f"{d.a}/{len(d.b)}")
        elif d.kind in ('import','include'):
            if d.kind=='import':
                as_name=("$"+d.b) if d.c else d.b
                isd=bool(d.c)
            else:
                as_name=None; isd=False
            deps.append({"as": as_name, "is_data": isd, "relpath": d.a})
