    return info

def check_module(info):
    if info.checked or info.is_data:
        return
    info.checked=True
    # construct nested defscope chain ending literal 0
    node=make_node('literal',0,0, Num(0))
    for d in reversed(info.directives):
        if d.kind=='moduledecl':
            continue
        node=make_node('defscope', d.pos,d.end, d, node)
    checker=Checker(info.src, info.filename)
    scope=base_scope()
    checker.check(node, scope)
    if checker.issues:
        raise CompileErrorList(checker.issues)

def load_module_exports(relpath, alias, is_data, importing_filename):
    path=resolve_module(relpath, is_data)
    info=load_module_info_by_path(path)
    if info.is_data:
        return {'funcs':[], 'info':info}
    check_module(info)
    # Compute exports
    funcs=set()
    for d in info.directives:
        if d.kind=='def':
            funcs.add((d.a, len(d.b)))
        elif d.kind=='include':
            sub=load_module_exports(d.a, None, False, info.filename)
            funcs.update(sub['funcs'])
    return {'funcs':list(funcs), 'info':info}

def get_module_env(info):
    if info.env is not None:
        return info.env
    env=CTX.base_env.clone() if CTX.base_env else Env()
    info.env=env # set before to handle cycles partially
    export_funcs={}
    for d in info.directives:
        if d.kind=='def':
            fn=UserFunction(d.a, d.b, d.c, env)
            env.funcs[(d.a,len(d.b))]=fn
            export_funcs[(d.a,len(d.b))]=fn
        elif d.kind=='import':
            # Apply import
            sub_path=resolve_module(d.a, d.c)
            sub_info=load_module_info_by_path(sub_path)
            if d.c:
                env.vars[d.b]=list(sub_info.data) if sub_info.is_data else None
            else:
                sub_env=get_module_env(sub_info)
                sub_exports=get_module_export_funcs(sub_info)
                for sig, fn in sub_exports.items():
                    env.funcs[(f"{d.b}::{sig[0]}", sig[1])]=fn
        elif d.kind=='include':
            sub_path=resolve_module(d.a, False)
            sub_info=load_module_info_by_path(sub_path)
            sub_env=get_module_env(sub_info)
            sub_exports=get_module_export_funcs(sub_info)
            for sig, fn in sub_exports.items():
                env.funcs[sig]=fn
                export_funcs[sig]=fn
        elif d.kind=='moduledecl':
            continue
    info.export_funcs=export_funcs
    return env

def get_module_export_funcs(info):
    if info.is_data:
        return {}
    if info.export_funcs:
        return info.export_funcs
    # build env to populate
    get_module_env(info)
    return info.export_funcs

def apply_import_to_env(env, directive):
    newenv=env.clone()
    info_path=resolve_module(directive.a, directive.c)
    info=load_module_info_by_path(info_path)
    if directive.c:
        newenv.vars[directive.b]=list(info.data) if info.is_data else None
    else:
        sub_exports=get_module_export_funcs(info)
        for sig, fn in sub_exports.items():
            newenv.funcs[(f"{directive.b}::{sig[0]}", sig[1])]=fn
    return newenv

def apply_include_to_env(env, directive):
    newenv=env.clone()
    info_path=resolve_module(directive.a, False)
    info=load_module_info_by_path(info_path)
    sub_exports=get_module_export_funcs(info)
    for sig, fn in sub_exports.items():
        newenv.funcs[sig]=fn
    return newenv

def modulemeta_value(name):
    try:
        path=resolve_module(name, False)
    except ModuleNotFoundIssue as e:
        raise error_jq(f"module not found: {name}")
    info=load_module_info_by_path(path)
    meta={}
    if info.meta_node is not None:
        ok,val=const_eval(info.meta_node)
        if ok and isinstance(val, dict):
            meta=dict(val)
    # deps: convert deps list (values already dict with python bools/string)
    deps=[]
    for dep in info.deps_list:
        deps.append({"as": dep["as"], "is_data": dep["is_data"], "relpath": dep["relpath"]})
    meta["deps"]=deps
    meta["defs"]=list(info.defs_list)
    return meta

