        p=self.current_parser
        p.skip_ws()
        if p.pos>=p.n:
            raise SourceExhausted()
        try:
            v=p.parse_value()
        except JSONParseError as e:
            raise ParseErrorSignal(e.msg)
        end_line=p.line_col(p.pos-1 if p.pos>0 else p.pos)[0]
        self._set_current_after_value(end_line)
        return v
    def _next_stream(self):
        if self.stream_queue:
            v=self.stream_queue.pop(0)
