                else:
                    # discard silently
                    continue
            if seg=="":
                continue
            if seg.strip()=="":
                continue
            # parse seg as one JSON value
            parser=JSONParser(seg)
            try:
                parser.skip_ws()
                if parser.pos>=parser.n:
                    continue
                v=parser.parse_value()
                parser.skip_ws()
