            except JSONParseError as e:
                # determine if it's last segment and EOF truncated numeric
                is_last=(self.seq_idx>=len(self.seq_segments))
                text=self.current_text or ""
                # global line roughly: count newlines before this segment occurrence - approximated by parser line + lines before segment in text
                # Find segment offset
                # simpler: use total lines up to end of segment
                # Compute line at end of this segment in original text: search
                # We'll approximate with e.line + number of newlines in text before RS separating this segment (difficult). Accept e msg but adjust line to global end line if at EOF.
                if is_last and seg and not seg.endswith('\n') and re.match(r'\s*-?[0-9.]+$', seg.strip()):
                    # truncated numeric
                    line=text.count('\n')+1
                    col=len(seg.strip())  # rough
                    sys.stderr.write(f"jq: ignoring parse error: Potentially truncated top-level numeric value at EOF at line {line}, column {col}\n")
                else:
                    # Modify line: if e.msg contains line X, we will keep but add global offset: count newlines in preceding segments + RS lines
                    # compute preceding text
                    # locate segment position by reconstructing split? Use find from sequential offset stored
                    msg=e.msg
                    # try to bump line number by lines before this segment in full text (approx: count newlines before segment start)
                    # Find segment start offset via cumulative lengths
                    offset=0
                    for s in self.seq_segments[:self.seq_idx-1]:
                        offset+=len(s)+1
                    global_line_before=(self.current_text or "")[:offset].count('\n')
                    # adjust msg line numbers: replace 'at line N,' with global
                    def repl(m):
                        orig=int(m.group(1))
                        return f"at line {orig+global_line_before},"
                    msg2=re.sub(r'at line ([0-9]+),', repl, msg)
                    sys.stderr.write(f"jq: ignoring parse error: {msg2} (need RS to resync)\n")
                continue
            # success: line number = lines up to end of segment
            # compute end line
            offset=0
            for s in self.seq_segments[:self.seq_idx]:
                offset+=len(s)+1
            line=(self.current_text or "")[:max(0,offset-1)].count('\n')+1
            self._set_current_after_value(line)
            return v

class SourceExhausted(Exception):
    pass

