    def __init__(self, text):
        self.text=text
        self.n=len(text)
        self.pos=0
        if self.pos<self.n and self.text[self.pos]=='\ufeff':
            self.pos+=1
    def line_col(self, pos):
        upto=self.text[:pos]
        line=upto.count('\n')+1
        last=upto.rfind('\n')
        col=pos-last-1 if last>=0 else pos
        return line, col
    def err(self, base_msg, pos=None, at_eof=False):
        if pos is None: pos=self.pos
        upto=self.text[:pos]
        line=upto.count('\n')+1
        last=upto.rfind('\n')
        if at_eof:
            col=(pos-(last+1)) if last>=0 else pos
        else:
            col=(pos-last) if last>=0 else pos+1
        if at_eof:
            msg=f"{base_msg} at EOF at line {line}, column {col}"
        else:
            msg=f"{base_msg} at line {line}, column {col}"
        raise JSONParseError(msg, line, col)
    def err_token_end(self, base_msg, endpos):
        # error reported at end of a scanned token (col is chars since line start)
        upto=self.text[:endpos]
        line=upto.count('\n')+1
        last=upto.rfind('\n')
        col=endpos-(last+1) if last>=0 else endpos
        raise JSONParseError(f"{base_msg} at line {line}, column {col}", line, col)
    def skip_ws(self):
        while self.pos<self.n and self.text[self.pos] in ' \t\r\n':
            self.pos+=1
    def peek(self):
        return self.text[self.pos] if self.pos<self.n else ''
    def parse_value(self):
        self.skip_ws()
        if self.pos>=self.n:
            self.err("Unfinished JSON term", at_eof=True)
        ch=self.text[self.pos]
