                elif esc=='\\': out.append('\\'); i+=2
                elif esc=='/': out.append('/'); i+=2
                elif esc=='b': out.append('\b'); i+=2
                elif esc=='f': out.append('\f'); i+=2
                elif esc=='n': out.append('\n'); i+=2
