    if any(len(p)==0 for p in paths):
        outs=update_fn(cur)
        return outs[0] if outs else _DELETED
    # group by first component, preserving order and distinct raw comps that normalize same for lists? We'll group later per container.
    # Container creation for null
    if cur is None:
        first=paths[0][0]
        cur={} if isinstance(first,str) else []
    if isinstance(cur, dict):
        groups={}; order=[]
        for p in paths:
            k=p[0]
            if not isinstance(k,str):
                index_value(cur,k) # raise appropriate
            if k not in groups:
                groups[k]=[]; order.append(k)
            groups[k].append(p[1:])
        result={}
        for k,child in cur.items():
            if k in groups:
                nr=modify_paths_value(child, groups[k], update_fn)
                if nr is not _DELETED:
                    result[k]=nr
            else:
                result[k]=child
        for k in order:
            if k not in cur:
                nr=modify_paths_value(None, groups[k], update_fn)
                if nr is not _DELETED:
