                if actual not in index_groups:
                    index_groups[actual]=[]; order.append(actual)
                index_groups[actual].append(p[1:])
            else:
                index_value(cur, comp) # raise
        result=[]
        # track original index mapping for slice after index modifications: We'll first build per-element result list with placeholders for deleted
        built=[]
