class StreamParseError(Exception):
    def __init__(self, msg, path, line=1):
        self.msg=msg; self.path=path; self.line=line

class StreamParser(JSONParser):
    def __init__(self, text):
        super().__init__(text)
        self.depth=0
    def event_line(self):
        return self.text[:self.pos].count('\n')+1
    def raise_stream(self, msg, path):
        raise StreamParseError(msg, path, self.event_line())
    def parse_events(self, path):
        # generator of (event,line)
        self.skip_ws()
        if self.pos>=self.n:
            self.err("Unfinished JSON term", at_eof=True)
        ch=self.text[self.pos]
        if ch=='{':
            yield from self.parse_object_events(path); return
        if ch=='[':
            yield from self.parse_array_events(path); return
        if ch==',':
            self.err("Expected value before ','", pos=self.pos)
        if ch=='}':
            self.err("Unmatched '}'", pos=self.pos)
        if ch==']':
            self.err("Unmatched ']'", pos=self.pos)
        # scalar/string
        start_pos=self.pos
        try:
            if ch=='"':
                v=self.parse_string()
                yield ([path, v], self.event_line()); return
            else:
                # check token completeness if nested and EOF terminated
                token_start=self.pos
                v=self.parse_scalar_token()
                if self.depth>0 and self.pos>=self.n:
                    # token may be truncated
                    self.err("Unfinished JSON term", at_eof=True)
                yield ([path, v], self.event_line()); return
        except JSONParseError as e:
            raise StreamParseError(e.msg, path, e.line)
    def parse_array_events(self, path):
        self.pos+=1; self.depth+=1
        try:
            self.skip_ws()
            if self.peek()==']':
                self.pos+=1; yield ([path, []], self.event_line()); return
            idx=0; last_idx=0
            while True:
                self.skip_ws()
                if self.pos>=self.n:
                    self.err("Unfinished JSON term", at_eof=True)
                if self.peek()==']':
                    self.err("Expected another array element", pos=self.pos)
                last_idx=idx
                try:
                    yield from self.parse_events(path+[num_from_py_int(idx)])
                except StreamParseError:
                    raise
                except JSONParseError as e:
                    raise StreamParseError(e.msg, path+[num_from_py_int(idx)], e.line)
                idx+=1
                self.skip_ws()
                if self.pos>=self.n:
                    self.err("Unfinished JSON term", at_eof=True)
                ch=self.text[self.pos]
                if ch==',':
                    self.pos+=1; continue
                elif ch==']':
                    self.pos+=1; yield ([path+[num_from_py_int(last_idx)]], self.event_line()); return
                else:
