        except JSONParseError as e:
            # Determine error path: if it's unfinished at EOF, current element path is path+[last], else path?
            # Caller may already have converted. At this level, if e is from a subvalue it'll be StreamParseError, not JSON.
            raise StreamParseError(e.msg, path, e.line)
        finally:
            self.depth-=1
    def parse_object_events(self, path):
        self.pos+=1; self.depth+=1
        try:
            self.skip_ws()
            if self.peek()=='}':
                self.pos+=1; yield ([path, {}], self.event_line()); return
            last_key=None
